using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CastleHandoverTests
{
    static readonly EntityId Site=new("site:kofu"),Owner=new("org:takeda"),Occupier=new("org:oda"),Receiver=new("person:nobunaga"),Muster=new("decision:castle-recipient");
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    internal static WorldSession Start(bool arrived=true,bool willing=true,string? policy=null){var w=NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",42,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:policy??CastleHandover.Policy);w.CommitSequence++;NpcArmies.Muster(w,Muster,Receiver,Occupier);var s=new WorldSession(w);if(arrived){Good(s.Submit(NpcArmies.Move(s.DiagnosticSnapshot(),Muster,"request:castle-recipient-trip","kofu"),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Receiver).Legs[^1].EndAt);}if(!willing){var unwilling=s.DiagnosticSnapshot();unwilling.Characters=unwilling.Characters.Select(c=>c.Id==Receiver?c with{WillObey=false}:c).ToArray();s=new WorldSession(unwilling);}return s;}
    static EntityId Offer(WorldSession s){var id=new EntityId("request:castle-offer/"+s.Revision);Good(s.ManageCastle(new(id,CastleAction.Offer,Site,RecipientOwner:Occupier),s.PlayerControl,s.Revision));return id;}
    static CommandResult Act(WorldSession s,CastleAction a,EntityId job,string? id=null)=>s.ManageCastle(new(new(id??"request:castle-step/"+s.Revision),a,Site,job),s.PlayerControl,s.Revision);
    static EntityId Gate(WorldSession s){var id=Offer(s);Good(Act(s,CastleAction.Confirm,id));Good(Act(s,CastleAction.Gate,id));return id;}
    [Fact]public void AgreementDoesNotMoveAnyPossessionOrProperty(){var s=Start();var before=s.DiagnosticSnapshot();var id=Offer(s);Good(Act(s,CastleAction.Confirm,id));var j=CastleHandover.Jobs(s.DiagnosticSnapshot()).Single();Assert.Null(j.Gate);Assert.Null(j.Occupied);Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(s.DiagnosticSnapshot().LandRights));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));}
    [Fact]public void GateThenScheduledKeepAreDistinctRealClockSteps(){var s=Start();var id=Gate(s);var now=s.Seconds;Good(Act(s,CastleAction.RequestKeep,id));Assert.Null(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Occupied);Assert.Equal(now,s.Seconds);Advance(s,now+1);var j=CastleHandover.Jobs(s.DiagnosticSnapshot()).Single();Assert.NotNull(j.Gate);Assert.Equal(now+1,j.Occupied!.At);Assert.Contains("軍事占有",s.CastleView()!.Castles.Single().Status);}
    [Fact]public void AbsentForeignArmyCannotBecomeAnInstantInvader(){var s=Start(false);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCastle(new(new("request:absent-castle"),CastleAction.Offer,Site,RecipientOwner:Occupier),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RefusedLocalTermsCannotBeConfirmed(){var s=Start(willing:false);var id=Offer(s);Assert.False(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Terms.Agreed);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.Confirm,id).Code);Assert.DoesNotContain(s.DiagnosticSnapshot().Castles!.Entries,e=>e.Input.Action==CastleAction.Gate);}
    [Fact]public void KeepCannotBeRequestedBeforeGate(){var s=Start();var id=Offer(s);Good(Act(s,CastleAction.Confirm,id));Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.RequestKeep,id).Code);}
    [Fact]public void CancellationBeforeGateKeepsAllOriginalAssets(){var s=Start();var id=Offer(s);Good(Act(s,CastleAction.Cancel,id));Assert.NotNull(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Cancelled);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.Confirm,id).Code);}
    [Fact]public void GateCannotBeUndoneByCancellation(){var s=Start();var id=Gate(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.Cancel,id).Code);Assert.NotNull(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Gate);}
    [Fact]public void PublicCallerCannotResolveSystemBoundary(){var s=Start();var id=Gate(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.ResolveKeep,id).Code);}
    [Fact]public void OccupationDoesNotTransferMembersBondsUnitsRightsOrMoney(){var s=Start();var id=Gate(s);var before=s.DiagnosticSnapshot();Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);var after=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(after.Memberships));Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(after.ServiceBonds));Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(after.Offices));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(after.LandRights));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(after.Units));Assert.Equal(NewGameWork.Balance(before,s.PlayerControl),NewGameWork.Balance(after,s.PlayerControl));Assert.Equal(Owner,CastleHandover.Jobs(after).Single().Terms.Owner);}
    [Fact]public void RepeatedInputIsIdempotentAndDifferentPayloadConflicts(){var s=Start();var i=new CastleInput(new("request:castle-once"),CastleAction.Offer,Site,RecipientOwner:Occupier);Good(s.ManageCastle(i,s.PlayerControl,s.Revision));var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCastle(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCastle(i with{RecipientOwner=new("org:hojo")},s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void WrongActorAndStaleRevisionCannotHandOver(){var s=Start();var i=new CastleInput(new("request:castle-wrong"),CastleAction.Offer,Site,RecipientOwner:Occupier);Assert.Equal(ResultCode.NotAvailable,s.ManageCastle(i,Receiver,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.ManageCastle(i,s.PlayerControl,s.Revision-1).Code);}
    [Fact]public void OldV18SaveKeepsNoCastleLedger(){var s=Start(false,policy:PersonalLife.Policy);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Null(s.CastleView());Assert.Null(s.DiagnosticSnapshot().Castles);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));}
    static void Send(WorldSession s,NewMilitaryAction action){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:castle-guard/"+s.Revision),action){AuthorityPolicy=action==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=action==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=action==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=action==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}
    static void GuardPermission(WorldSession s){void Open(){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}Send(s,NewMilitaryAction.Request);Advance(s,s.Seconds+2);Open();Send(s,NewMilitaryAction.Accept);Advance(s,s.Seconds+2);Open();}
    [Theory][InlineData(false)][InlineData(true)]public void GuardBeforeBoundaryHoldsKeepButLaterMobilizationDoesNotUndo(bool late){var s=Start();GuardPermission(s);var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));if(!late)Send(s,NewMilitaryAction.Pickup);Advance(s,s.Seconds+1);if(late)Send(s,NewMilitaryAction.Pickup);var j=CastleHandover.Jobs(s.DiagnosticSnapshot()).Single();Assert.NotNull(j.Gate);Assert.Equal(late,j.Occupied!=null);if(!late){Assert.Equal("relief-hold",j.Resolution!.Outcome);Assert.True(s.CastleView()!.Castles.Single().CanRequestKeep);}else Assert.Contains("係争",s.CastleView()!.Castles.Single().Status);}
    [Fact]public void HeldGuardRemainsSameOwnerAndSoldiersAfterFailedKeep(){var s=Start();GuardPermission(s);Send(s,NewMilitaryAction.Pickup);var id=Gate(s);var before=s.DiagnosticSnapshot();Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);Assert.Null(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Occupied);Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));}
    [Fact]public void SalaryDebtAndPrivateRiceSurviveMilitaryOccupation(){var s=Start();var worker=HistoricalHouseholdCatalog.Edition.People.Single().Id;var term=new EntityId("request:castle-salary");Good(s.ManageSalary(new(term,SalaryAction.Propose,worker,Site,Amount:20),s.PlayerControl,s.Revision));Good(s.ManageSalary(new(new("request:castle-confirm-salary"),SalaryAction.Confirm,worker,Site,term),s.PlayerControl,s.Revision));Advance(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[0]);var id=Gate(s);long debt=s.PersonalLifeView()!.StipendPayable;var before=s.DiagnosticSnapshot();Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);Assert.Equal(20,debt);Assert.Equal(debt,s.PersonalLifeView()!.StipendPayable);Assert.Equal(ContractJson.Write(before.Salary),ContractJson.Write(s.DiagnosticSnapshot().Salary));Assert.Equal(ContractJson.Write(before.Communities!.Accounts),ContractJson.Write(s.DiagnosticSnapshot().Communities!.Accounts));}
    [Fact]public void PendingKeepCannotBeRequestedTwiceOrSkippedBySave(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.RequestKeep,id).Code);var w=s.DiagnosticSnapshot();w.ElapsedSeconds++;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void PartialGateSurvivesDeadlineAndCannotBeCancelledLater(){var s=Start();var id=Gate(s);Advance(s,CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Terms.Until+1);Assert.NotNull(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Gate);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.RequestKeep,id).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CastleAction.Cancel,id).Code);}
    [Fact]public void LeavingBeforeScheduledKeepHidesRemoteOutcome(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:castle-person-away","castle"),s.Revision));Advance(s,s.Seconds+2);var card=s.CastleView()!.Castles.Single();Assert.False(card.Local);Assert.Null(card.RecipientSoldiers);Assert.Null(card.IncumbentSoldiers);Assert.Contains("現況未確認",card.Status);Assert.Null(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Occupied);}
    [Fact]public void ReceiverDepartureBlocksScheduledKeepWithoutUndoingGate(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Good(s.Submit(NpcArmies.Move(s.DiagnosticSnapshot(),Muster,"request:castle-receiver-away","castle"),s.Revision));Advance(s,s.Seconds+2);var j=CastleHandover.Jobs(s.DiagnosticSnapshot()).Single();Assert.Null(j.Occupied);Assert.Equal("absent",j.Resolution!.Outcome);Assert.NotNull(j.Gate);}
    [Fact]public void CompletedRecordDoesNotPretendAbsentArmyStillOccupies(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);Good(s.Submit(NpcArmies.Move(s.DiagnosticSnapshot(),Muster,"request:castle-after-keep-away","castle"),s.Revision));Advance(s,s.Seconds+100);Good(Act(s,CastleAction.Observe,id));Assert.NotNull(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Occupied);Assert.Contains("不在",s.CastleView()!.Castles.Single().Status);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedTermsTimestampWitnessOrOutcomeAreRejected(int kind){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);var w=s.DiagnosticSnapshot();var es=w.Castles!.Entries.ToArray();if(kind==0)es[0]=es[0] with{Terms=es[0].Terms! with{Occupier=Owner}};if(kind==1)es[^1]=es[^1] with{At=es[^1].At-1};if(kind==2)es[^1]=es[^1] with{Witness=false};if(kind==3)es[^1]=es[^1] with{Outcome="relief-hold"};w.Castles=w.Castles with{Entries=es};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void CastleIdsCannotBeReusedForPersonalLife(){var s=Start();var id=Offer(s);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageLife(new(id,LifeAction.SetGoal,Site,Target:20),s.PlayerControl,s.Revision).Code);}
    [Fact]public void PersonalLifeIdsCannotBeReusedForCastle(){var s=Start();var id=new EntityId("request:castle-shared");Good(s.ManageLife(new(id,LifeAction.SetGoal,Site,Target:20),s.PlayerControl,s.Revision));Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCastle(new(id,CastleAction.Offer,Site,RecipientOwner:Occupier),s.PlayerControl,s.Revision).Code);}
    [Fact]public void UnknownCurrentSiteViewDoesNotInventOwnership(){var s=Start(false);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:castle-fork","fork"),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt);Assert.Empty(s.CastleView()!.LocalRecipients);}
    [Fact]public void PendingKeepPreventsStartingPrivateRest(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Assert.Equal(ResultCode.NotAvailable,s.ManageLife(new(new("request:castle-rest"),LifeAction.RestOutside,Site),s.PlayerControl,s.Revision).Code);}
    [Fact]public void NormalProfileBuildEnablesCastleWithoutChangingV18(){var seed=Start(false).DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"castle-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(seed.Start,[],seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,CastleHandover.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.CastleView());Assert.NotNull(s.PersonalLifeView());Assert.True(RoadConvoy.Enabled(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void ActualGenerationPartialGateKeepReliefAndFuture(int phase){var a=Start();EntityId id;if(phase is 5 or 6){GuardPermission(a);id=Gate(a);Send(a,NewMilitaryAction.Pickup);}else{id=Offer(a);if(phase>=1)Good(Act(a,CastleAction.Confirm,id));if(phase>=2&&phase!=7)Good(Act(a,CastleAction.Gate,id));}if(phase is 3 or 4 or 5 or 6){Good(Act(a,CastleAction.RequestKeep,id));if(phase is 4 or 5 or 6)Advance(a,a.Seconds+1);}if(phase==6)Good(Act(a,CastleAction.Observe,id));if(phase==7)Good(Act(a,CastleAction.Cancel,id));a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"castle-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"castle",w.WorldId).Published);var host=new WorldSessionHost(Start(false));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("castle"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CastleView()),ContractJson.Write(b.CastleView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"castle-handover-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"castle-handover-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b})Advance(q,q.Seconds+10);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CastleView()),ContractJson.Write(b.CastleView()));}

    [Fact]public void NewOptionalWorldSectionDoesNotMakeCharacterLifeOptional(){var w=Start(false).DiagnosticSnapshot();var n=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(w.Characters[0]))!.AsObject();Assert.True(n.Remove("Life"));Assert.Throws<InvalidDataException>(()=>ContractJson.Read<CharacterState>(System.Text.Encoding.UTF8.GetBytes(n.ToJsonString())));}
    [Fact]public void CastleViewStillRequiresItsCastleArray(){var s=Start(false);var n=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.CastleView()))!.AsObject();Assert.True(n.Remove("Castles"));Assert.Throws<InvalidDataException>(()=>ContractJson.Read<CastleView>(System.Text.Encoding.UTF8.GetBytes(n.ToJsonString())));}
    [Fact]public void TwoOffersCannotShareACommitRevision(){var s=Start();Offer(s);var w=s.DiagnosticSnapshot();var e=w.Castles!.Entries.Single();var id=new EntityId("request:castle-forged-second");w.Castles=w.Castles with{Entries=[e,e with{Input=e.Input with{Id=id},Terms=e.Terms! with{Id=id}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void RemoteWitnessRecordDoesNotRevealDifferentCurrentReceiverMotion(){var s=Start();var id=Gate(s);Good(Act(s,CastleAction.RequestKeep,id));Advance(s,s.Seconds+1);Good(Act(s,CastleAction.Observe,id));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:castle-witness-away","castle"),s.Revision));Advance(s,s.Seconds+2);var a=new WorldSession(s.DiagnosticSnapshot());var b=new WorldSession(s.DiagnosticSnapshot());Good(b.Submit(NpcArmies.Move(b.DiagnosticSnapshot(),Muster,"request:castle-hidden-move","castle"),b.Revision));Advance(a,a.Seconds+100);Advance(b,b.Seconds+100);Assert.Equal(ContractJson.Write(a.CastleView()),ContractJson.Write(b.CastleView()));Assert.Contains("立会日時",a.CastleView()!.Castles.Single().Status);}

    [Fact]public void ActualAutonomousRaidWaitsDuringConfirmedHandoverThenResumesAfterCancellation(){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:"site:fork");var setup=NewGameWorldTests.Setup([p],[new(p.Id,"org:castle-raid",[p.Site],false)]);var w=NewGameWorld.Create(setup.World,setup.Registered,p.Id,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:CastleHandover.Policy);w.CommitSequence++;FactionStances.Apply(w,new(new("decision:castle-real-raid"),FactionStanceAction.DeclareHostile,Occupier,new("org:castle-raid"),0,1000000),Receiver);var s=new WorldSession(w);Advance(s,2);var army=Assert.Single(s.DiagnosticSnapshot().NpcArmies!.Musters);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Receiver).Legs[^1].EndAt);var id=new EntityId("request:castle-real-local-offer");var site=new EntityId("site:fork");Good(s.ManageCastle(new(id,CastleAction.Offer,site,RecipientOwner:Occupier),s.PlayerControl,s.Revision));Good(s.ManageCastle(new(new("request:castle-real-confirm"),CastleAction.Confirm,site,id),s.PlayerControl,s.Revision));Assert.True(CastleHandover.HoldsNpc(s.DiagnosticSnapshot(),army.Id));Advance(s,s.Seconds+100);Assert.Empty(s.DiagnosticSnapshot().NpcArmies!.Returns);Assert.Single(s.DiagnosticSnapshot().NpcArmies!.Marches);Good(s.ManageCastle(new(new("request:castle-real-cancel"),CastleAction.Cancel,site,id),s.PlayerControl,s.Revision));Assert.False(CastleHandover.HoldsNpc(s.DiagnosticSnapshot(),army.Id));Advance(s,s.Seconds+2);Assert.Equal(2,s.DiagnosticSnapshot().NpcArmies!.Marches.Length);}

}
